INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "孙儒攻取扬州，杨行密出奔", "start_year": 888, "end_year": 888, "time_original": "888年四月壬午", "dynasty": "唐", "description": "孙儒袭取扬州，杨行密离城；孙儒自称淮南节度使。", "phases": [], "location_name": "扬州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "2ccb0980-8e9e-5a4a-9617-02ca5e136d10"}, {"title": "袁袭劝杨行密归庐州", "start_year": 888, "end_year": 888, "time_original": "杨行密出扬州后；具体日未载", "dynasty": "唐", "description": "杨行密原想奔海陵，袁袭劝其归庐州另谋进取，杨行密采纳。", "phases": [], "location_name": "扬州、庐州方向", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "15b64cb5-64c5-5d55-afc8-144122e9ebc4"}, {"title": "朱全忠遣丁会等援河阳", "start_year": 888, "end_year": 888, "time_original": "888年四月；具体日未载", "dynasty": "唐", "description": "朱全忠遣丁会、葛从周、牛存节率军援河阳。", "phases": [], "location_name": "河阳", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e500666d-7e59-589f-af42-c4263b66f388"}, {"title": "河阳援军击败李存孝等", "start_year": 888, "end_year": 888, "time_original": "朱全忠援军抵河阳后；具体日未载", "dynasty": "唐", "description": "李存孝率骑兵在温迎战，李罕之率步兵攻城，河东军战败；安休休奔蔡州。汴军拟断太行路，康君立等引兵还。", "phases": [], "location_name": "河阳、温、太行路", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "96d5650f-1db8-586f-a595-a29fdf7ac2b3"}, {"title": "朱全忠奏丁会河阳留后、张全义河南尹", "start_year": 888, "end_year": 888, "time_original": "河阳战后；具体日未载", "dynasty": "唐", "description": "朱全忠奏请丁会为河阳留后，复任张全义为河南尹。", "phases": [], "location_name": "河阳、河南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "892d5278-e66e-57f5-abd4-ad0d578b15ac"}, {"title": "张全义为朱全忠供军粮器", "start_year": null, "end_year": null, "time_original": "河阳获救后；具体年日未载", "dynasty": "唐", "description": "张全义感念朱全忠援助，之后朱全忠出战时由张全义供给粮食、器仗。", "phases": [], "location_name": "河南、宣武方向", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7ec8b7f9-8bde-5a7a-a084-6c2676d63e18"}, {"title": "李罕之返泽州，遣子侍李克用", "start_year": 888, "end_year": 888, "time_original": "河阳兵败后；具体日未载", "dynasty": "唐", "description": "李罕之任泽州刺史、领河阳节度使，留其子颀侍李克用，自己返泽州。", "phases": [], "location_name": "泽州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "badfe0bf-faf7-5d71-b4ab-428a15600e96"}, {"title": "李罕之据泽州劫掠周边", "start_year": null, "end_year": null, "time_original": "李罕之返泽州后至此后多年；确年未载", "dynasty": "唐", "description": "《通鉴》概述李罕之据泽州后长期掠夺，周边官府与耕作受严重破坏。", "phases": [], "location_name": "怀、孟、晋、绛一带", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d59f421a-380c-5df2-a394-7aeea5bfef89"}, {"title": "李罕之攻取摩云山", "start_year": null, "end_year": null, "time_original": "李罕之据泽州后；具体年日未载", "dynasty": "唐", "description": "李罕之攻取河中、绛州间民众聚保的摩云山，因而被时人称为“李摩云”。", "phases": [], "location_name": "摩云山", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f5a4d040-b10b-5df7-ab1e-0c7ecf6988ad"}, {"title": "乐从训被程公信击杀", "start_year": 888, "end_year": 888, "time_original": "888年四月癸巳前", "dynasty": "唐", "description": "乐从训移军洹水，罗弘信遣程公信进击，乐从训被斩，其与父乐彦祯的首级都被悬于军门。", "phases": [], "location_name": "洹水、魏州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "aff23e29-98cb-5718-9d19-0c08f2639ad5"}, {"title": "罗弘信与朱全忠修好", "start_year": 888, "end_year": 888, "time_original": "888年四月癸巳", "dynasty": "唐", "description": "罗弘信派使者厚礼犒朱全忠军并请求修好，朱全忠召军返；朝廷诏罗弘信权知魏博留后。", "phases": [], "location_name": "魏博、汴军方向", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "bb08e66a-3c34-5fe1-8f15-9439e1bb0914"}, {"title": "郭禹逐王建肇据荆南", "start_year": 888, "end_year": 888, "time_original": "888年四月前后；具体日未载", "dynasty": "唐", "description": "归州刺史郭禹进攻荆南，逐王建肇出逃黔州；朝廷诏郭禹为荆南留后。", "phases": [], "location_name": "荆南、黔州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "482c8aef-d98f-5cae-b352-fc08c38e8d10"}, {"title": "郭禹抚集荆南，晚年人口恢复", "start_year": null, "end_year": null, "time_original": "郭禹治荆南期间至晚年；确年未载", "dynasty": "唐", "description": "《通鉴》记郭禹治理荆南、招抚流民、通商劝农，至晚年户数恢复。", "phases": [], "location_name": "荆南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "199820b7-810f-541f-bad9-6ddf078169c6"}, {"title": "韩建于华州招民劝农", "start_year": null, "end_year": null, "time_original": "韩建治华州数年间；确年未载", "dynasty": "唐", "description": "《通鉴》比较记述韩建在华州招抚流民、劝课农桑，数年间民富军赡，时人称北韩南郭。", "phases": [], "location_name": "华州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "60792715-4193-5fb8-b353-7556d95974ed"}, {"title": "郭禹与许存夺夔州", "start_year": null, "end_year": null, "time_original": "郭禹治荆南期间；具体年日未载", "dynasty": "唐", "description": "秦宗权别将常厚据夔州，郭禹与其将许存攻取。", "phases": [], "location_name": "夔州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e8a8425a-6843-578f-a583-ce544c9cbdb1"}, {"title": "郭禹后授荆南节度使并复名成汭", "start_year": null, "end_year": null, "time_original": "郭禹据荆南久之；具体年未载", "dynasty": "唐", "description": "朝廷后来授郭禹荆南节度使、王建肇武泰节度使；郭禹奏请恢复姓名为成汭。", "phases": [], "location_name": "荆南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4de76608-8e9a-5bba-af48-c79f238891cc"}, {"title": "李克用加兼侍中", "start_year": 888, "end_year": 888, "time_original": "888年四月；具体日未载", "dynasty": "唐", "description": "朝廷加李克用兼侍中。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "cf57a63e-3094-59a6-9457-af86f9d4a5c6"}, {"title": "朱全忠加兼侍中", "start_year": 888, "end_year": 888, "time_original": "888年五月己亥", "dynasty": "唐", "description": "朝廷加朱全忠兼侍中。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "b194b162-7e8b-5bca-bc35-e868bdce0fb5"}, {"title": "赵德諲举山南东道降朱全忠", "start_year": 888, "end_year": 888, "time_original": "888年五月壬寅", "dynasty": "唐", "description": "赵德諲失荆南后判断秦宗权将败，率山南东道归降，托附朱全忠。", "phases": [], "location_name": "山南东道", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "2389a21c-e7ae-5dc7-9ef2-ada167cd3ac1"}, {"title": "朝廷授赵德諲忠义军节度使", "start_year": 888, "end_year": 888, "time_original": "赵德諲归降后；具体日未载", "dynasty": "唐", "description": "朱全忠奏赵德諲为副，朝廷改山南东道为忠义军，授赵德諲节度使、蔡州四面行营副都统。", "phases": [], "location_name": "山南东道", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "391709a1-9603-5648-b42e-02f751cda267"}]'::jsonb)
